CREATE TABLE IF NOT EXISTS migrations(version INTEGER PRIMARY KEY,applied_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS settings(key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS projects(id TEXT PRIMARY KEY,title TEXT NOT NULL,description TEXT NOT NULL,revision INTEGER NOT NULL DEFAULT 0,archived INTEGER NOT NULL DEFAULT 0,data TEXT NOT NULL,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS revisions(project_id TEXT NOT NULL,revision INTEGER NOT NULL,snapshot TEXT NOT NULL,created_at TEXT NOT NULL,PRIMARY KEY(project_id,revision));
CREATE TABLE IF NOT EXISTS changes(id TEXT PRIMARY KEY,project_id TEXT NOT NULL,request_id TEXT NOT NULL UNIQUE,base_revision INTEGER NOT NULL,operations TEXT NOT NULL,status TEXT NOT NULL,summary TEXT NOT NULL,reasons TEXT NOT NULL,source TEXT NOT NULL,conversation_id TEXT,scope TEXT NOT NULL,before_snapshot TEXT,after_snapshot TEXT,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS conversations(id TEXT PRIMARY KEY,project_id TEXT NOT NULL,module TEXT NOT NULL,entity_id TEXT,title TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS messages(id TEXT PRIMARY KEY,conversation_id TEXT NOT NULL,role TEXT NOT NULL,content TEXT NOT NULL,change_id TEXT,job_id TEXT,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS jobs(id TEXT PRIMARY KEY,project_id TEXT NOT NULL,conversation_id TEXT,kind TEXT NOT NULL,status TEXT NOT NULL,spec TEXT NOT NULL,base_revision INTEGER NOT NULL,result TEXT,error TEXT,attempt INTEGER NOT NULL DEFAULT 0,batch_id TEXT,depends_on TEXT NOT NULL DEFAULT '[]',created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS batches(id TEXT PRIMARY KEY,title TEXT NOT NULL,limits_json TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'running',created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS connections(id TEXT PRIMARY KEY,config TEXT NOT NULL,secret TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS usage(id TEXT PRIMARY KEY,job_id TEXT,project_id TEXT,connection_id TEXT,model TEXT,input_tokens INTEGER,output_tokens INTEGER,cost REAL,duration INTEGER,attempt INTEGER,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS files(id TEXT PRIMARY KEY,project_id TEXT NOT NULL,name TEXT NOT NULL,mime TEXT NOT NULL,path TEXT NOT NULL,size INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS releases(id TEXT PRIMARY KEY,project_id TEXT NOT NULL,revision INTEGER NOT NULL,format TEXT NOT NULL,audience TEXT NOT NULL,file_name TEXT NOT NULL,path TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS guidelines(id TEXT PRIMARY KEY,title TEXT NOT NULL,content TEXT NOT NULL,status TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sessions(id TEXT PRIMARY KEY,expires_at INTEGER NOT NULL);
